function getState(){return window.CropCollectorApp?.state}
function syncState(key,value){try{getState()?.set?.(key,value)}catch{}}
function collectorDebugEnabled(){try{return localStorage.getItem('collector_debug')==='true'}catch{return false}}
function collectorDebugLog(message,details){if(!collectorDebugEnabled())return;if(details===undefined)console.log(`[CollectorDebug] ${message}`);else console.log(`[CollectorDebug] ${message}`,details)}
function collectorDebugWarn(message,details){if(!collectorDebugEnabled())return;if(details===undefined)console.warn(`[CollectorDebug] ${message}`);else console.warn(`[CollectorDebug] ${message}`,details)}
function isDesktopPhotoOptional(){return !window.isMobileCollector?.()}
function useOdkCollectorLayout(){return true}
function enforceOdkCollectorShell(){document.body.classList.add('odk-layout')}
function getCurrentModule(){
  const stateValue=getState()?.get?.('activeCollectorPrimaryModule');
  const value=(stateValue&&stateValue!=='choose')?stateValue:(window.activeCollectorPrimaryModule&&window.activeCollectorPrimaryModule!=='choose'?window.activeCollectorPrimaryModule:null);
  if(value==='crop'||value==='livestock')return value;
  const surveyType=window.selectedSurveyType||window.effectiveModule||window.currentSurveyModule;
  return (surveyType==='crop'||surveyType==='livestock')?surveyType:null;
}
function getCurrentStep(){return Number(getState()?.get?.('currentCollectorWizardStep')??window.currentCollectorWizardStep??0)||0}
function getCurrentCropPlan(){return Array.isArray(getState()?.get?.('currentCropPlan'))?getState().get('currentCropPlan'):window.currentCropPlan||[]}
function setCurrentStep(value){window.currentCollectorWizardStep=value;syncState('currentCollectorWizardStep',value)}
function setCurrentModule(value){
  if(value==='choose'||!value)value=null;
  window.activeCollectorPrimaryModule=value;
  if(value==='crop'||value==='livestock'){
    window.selectedSurveyType=value;
    window.effectiveModule=value;
    window.currentSurveyModule=value;
  }
  syncState('activeCollectorPrimaryModule',value);
}
function setCurrentCropPlan(plan){window.currentCropPlan=plan;syncState('currentCropPlan',plan)}
function setCurrentCropPlanIndex(index){window.currentCropPlanIndex=index;syncState('currentCropPlanIndex',index)}
function setMobileWorkspaceValue(workspace){window.mobileWorkspace=workspace;syncState('mobileWorkspace',workspace)}

function createQuestionnaireGroup(id,title,note,badge,highlight=false){const group=document.createElement('section');group.id=id;group.className=`questionnaire-group${highlight?' questionnaire-highlight':''}`;group.innerHTML=`<div class="questionnaire-group-header"><div class="questionnaire-group-meta"><span class="questionnaire-group-badge">${badge}</span><div><h3 class="questionnaire-group-title">${title}</h3><p class="questionnaire-group-note">${note}</p></div></div></div><div class="questionnaire-group-body"></div>`;return group}
function moveGroupsToQuestionnaireSection(section,ids=[]){const body=section.querySelector('.questionnaire-group-body');ids.forEach(id=>{const group=document.getElementById(id)?.closest('.input-group');if(group&&body&&!body.contains(group))body.appendChild(group)})}
function getOrCreateQuestionnaireSection(parent,id,title,note,badge,highlight=false){let section=document.getElementById(id);if(section)return section;section=createQuestionnaireGroup(id,title,note,badge,highlight);parent?.appendChild(section);return section}
function getQuestionnaireGroups(){return [...document.querySelectorAll('.questionnaire-group')]}
function isRequiredCollectorFieldComplete(field){if(!field||field.disabled)return true;if(field.type==='hidden'||field.id==='photo-data')return true;if(field.tagName==='SELECT')return !!String(field.value||'').trim();if(field.type==='checkbox'||field.type==='radio')return !!field.checked;return !!String(field.value||'').trim()}
function qualityChipMarkup(assessment){if(!assessment)return'';return `<span class="quality-chip ${assessment.tier||'needs-work'}">${assessment.label||'Needs Work'} ${assessment.score||0}/100</span>`}
function getEntryQualityAssessment(entry){const source=entry||{};let score=0;const reasons=[];const values=[String(source.surveyName??document.getElementById('survey-name')?.value??'').trim(),String(source.ownerName??document.getElementById('owner-name')?.value??'').trim(),String(source.province??document.getElementById('province')?.value??'').trim(),String(source.district??document.getElementById('district')?.value??'').trim(),String(source.ward??document.getElementById('ward')?.value??'').trim(),String(source.sector??document.getElementById('sector')?.value??'').trim(),String(source.cropType??document.getElementById('crop-type')?.value??'').trim()];const complete=values.filter(Boolean).length;score+=Math.round((complete/7)*60);if(complete<7)reasons.push('required identity/location fields incomplete');if(source.geometry||window.selectedPolygon)score+=20;else reasons.push('geometry not ready');if(source.photoData||source.photoName||document.getElementById('photo-data')?.value)score+=20;else reasons.push('photo missing');const tier=score>=85?'excellent':score>=70?'good':score>=50?'fair':'needs-work';const label=tier==='excellent'?'Excellent':tier==='good'?'Good':tier==='fair'?'Fair':'Needs Work';return {score,tier,label,reasons}}

function injectCollectorFormSteps(){const form=document.getElementById('crop-form');const firstGroup=document.getElementById('survey-name')?.closest('.input-group');const saveBtn=document.getElementById('save-entry-btn');if(!form||!firstGroup||!saveBtn||document.getElementById('collect-step-toggle'))return;enforceOdkCollectorShell();const steps=document.createElement('div');steps.id='collect-step-toggle';steps.className='step-toggle';steps.innerHTML='<button type="button" id="collect-step-basic" class="active">Survey Setup</button><button type="button" id="collect-step-more" class="secondary">Field Details</button>';const basicPanel=document.createElement('div');basicPanel.id='collect-step-basic-panel';basicPanel.className='collect-step-panel';const morePanel=document.createElement('div');morePanel.id='collect-step-more-panel';morePanel.className='collect-step-panel';form.insertBefore(steps,firstGroup);form.insertBefore(basicPanel,saveBtn);form.insertBefore(morePanel,saveBtn);basicPanel.insertAdjacentHTML('beforeend','<div class="status" id="collect-basic-guidance" style="margin-bottom:.85rem">Start with the survey setup, then move into the field record step by step.</div>');morePanel.insertAdjacentHTML('beforeend','<div class="status" id="collect-more-guidance" style="margin-bottom:.85rem">Continue through the survey details for the current record.</div>');basicPanel.insertAdjacentHTML('beforeend','<div class="button-group" id="collect-step-basic-actions"><button type="button" id="collect-step-next" class="secondary"><i data-feather="arrow-right"></i> Continue to Field Details</button></div>');morePanel.insertAdjacentHTML('beforeend','<div class="button-group" id="collect-step-more-actions"><button type="button" id="collect-step-back" class="secondary"><i data-feather="arrow-left"></i> Back to Survey Setup</button></div>')}
function injectCropPlanSelector(){const cropSelect=document.getElementById('crop-type');if(!cropSelect)return;const host=cropSelect.closest('.input-group');if(host){host.hidden=false;host.style.display=''}const planner=document.getElementById('crop-plan-selector');if(planner)planner.remove()}
function injectCollectorQuestionnaireSections(){const basicPanel=document.getElementById('collect-step-basic-panel');const morePanel=document.getElementById('collect-step-more-panel');if(!basicPanel||!morePanel)return;let progress=document.getElementById('collector-questionnaire-progress');if(!progress){progress=document.createElement('div');progress.id='collector-questionnaire-progress';progress.className='questionnaire-progress';progress.innerHTML='<div class="questionnaire-progress-title">Survey progress</div><div class="questionnaire-progress-meta">The app tracks the required answers for the current record as you move along.</div>'}const visitSection=getOrCreateQuestionnaireSection(basicPanel,'collector-visit-section','Collector setup','Extension officer details are filled before the farmer questions.','1',true);moveGroupsToQuestionnaireSection(visitSection,['survey-name','questionnaire-id','aeo-name','aeo-contact-number']);const farmerSection=getOrCreateQuestionnaireSection(basicPanel,'collector-farmer-section','Farmer and contact details','Who owns or manages this record.','2');moveGroupsToQuestionnaireSection(farmerSection,['owner-name','farm-name','farmer-contact']);const locationSection=getOrCreateQuestionnaireSection(basicPanel,'collector-location-section','Location and crop identity','Administrative location, sector, AEZ, and crop identity.','3',true);moveGroupsToQuestionnaireSection(locationSection,['province','district','ward','aez','sector','crop-type','planted-area-ha','fertilizer-application','pest-disease-status']);const drawSection=getOrCreateQuestionnaireSection(basicPanel,'collector-draw-section','Map field first','Capture the field boundary before answering the crop form.','1',true);drawSection.querySelector('.questionnaire-group-body').innerHTML='<div class="status" id="collector-draw-guidance">Get a good GPS fix, draw the field polygon on the map, then continue.</div>';const householdSection=getOrCreateQuestionnaireSection(morePanel,'collector-household-section','Household profile and land holding','Household and land summary for this farmer.','5');const ministrySummaryBlock=document.getElementById('ministry-summary-fields');if(ministrySummaryBlock)householdSection.querySelector('.questionnaire-group-body').appendChild(ministrySummaryBlock);const agronomySection=getOrCreateQuestionnaireSection(morePanel,'collector-agronomy-section','Plot agronomy and input use','Planting window, inputs, and crop management details.','6');const ministryPlotBlock=document.getElementById('ministry-plot-fields');if(ministryPlotBlock)agronomySection.querySelector('.questionnaire-group-body').appendChild(ministryPlotBlock);const productionSection=getOrCreateQuestionnaireSection(morePanel,'collector-production-section','Growth, production, and expected yield','Current crop stage, condition, season, irrigation, and yield.','7');moveGroupsToQuestionnaireSection(productionSection,['growth-stage','crop-condition','season','irrigation-type','planting-date','harvest-date','yield-expected','yield-tonnes']);const productionDrawer=document.getElementById('collect-production-drawer');if(productionDrawer)productionSection.querySelector('.questionnaire-group-body').appendChild(productionDrawer);const evidenceSection=getOrCreateQuestionnaireSection(morePanel,'collector-evidence-section','Observations and photo evidence','Observation notes and photo evidence for the current record.','8',true);moveGroupsToQuestionnaireSection(evidenceSection,['observation-notes','post-harvest-assessment','notes']);const observationDrawer=document.getElementById('collect-observation-drawer');if(observationDrawer)evidenceSection.querySelector('.questionnaire-group-body').appendChild(observationDrawer);const basicActions=document.getElementById('collect-step-basic-actions');if(!basicPanel.contains(progress))basicPanel.appendChild(progress);if(!basicPanel.contains(drawSection))basicPanel.appendChild(drawSection);if(!basicPanel.contains(visitSection))basicPanel.appendChild(visitSection);if(!basicPanel.contains(farmerSection))basicPanel.appendChild(farmerSection);if(!basicPanel.contains(locationSection))basicPanel.appendChild(locationSection);if(basicActions&&!basicPanel.contains(basicActions))basicPanel.appendChild(basicActions);const moreActions=document.getElementById('collect-step-more-actions');if(!morePanel.contains(householdSection))morePanel.appendChild(householdSection);if(!morePanel.contains(agronomySection))morePanel.appendChild(agronomySection);if(!morePanel.contains(productionSection))morePanel.appendChild(productionSection);if(!morePanel.contains(evidenceSection))morePanel.appendChild(evidenceSection);if(moreActions&&!morePanel.contains(moreActions))morePanel.appendChild(moreActions);updateQuestionnaireProgress()}
function injectCollectorPrimaryModules(){const host=document.getElementById('collect-form');if(!host||document.getElementById('collector-primary-modules'))return;const card=document.createElement('div');card.id='collector-primary-modules';card.className='status';card.style.marginBottom='1rem';card.innerHTML='<div class="questionnaire-group-title" style="margin-bottom:.55rem">Start Survey</div><p style="margin:0 0 .75rem;color:#5f6f5f">Choose the survey name first. Then start a crop or livestock record and follow the guided steps.</p><div class="input-group" id="collector-survey-menu-group"><select id="collector-survey-name"><option value="" selected>Select survey name</option></select><label for="collector-survey-name">Survey Name</label></div><div class="button-group" id="collector-primary-module-switch" style="margin-top:.75rem"><button type="button" id="collector-open-crop"><span class="save-flow-chip">CROP</span> Start Crop Survey</button><button type="button" id="collector-open-livestock" class="secondary"><span class="save-flow-chip">LIVESTOCK</span> Start Livestock Survey</button></div><div class="status" id="collector-module-active-label" style="margin-top:.75rem">Choose a survey type to begin.</div><div id="collector-odk-nav" class="button-group" style="margin-top:.75rem"><button type="button" id="collector-odk-back" class="secondary">Back</button><button type="button" id="collector-odk-next">Next</button></div><div id="collector-odk-step-label" style="margin-top:.55rem;color:#5f6f5f">Choose a survey name, then start Crop or Livestock.</div>';host.insertBefore(card,host.querySelector('form'));syncCollectorSurveyMenu()}
function getCropPlanLabel(value){const option=[...document.querySelectorAll('#crop-type option')].find(node=>node.value===value);return option?.textContent?.trim()||value}
function syncCropPlanCheckboxes(){document.querySelectorAll('[data-crop-plan-option]').forEach(input=>{input.checked=getCurrentCropPlan().includes(input.value)})}
function renderCropPlanSummary(){const planner=document.getElementById('crop-plan-selector');const summary=document.getElementById('crop-plan-summary');const active=document.getElementById('crop-plan-active');const next=document.getElementById('crop-plan-next');if(!planner)return;planner.hidden=getCurrentModule()!=='crop';if(getCurrentModule()!=='crop'){if(summary)summary.innerHTML='';if(active)active.textContent='';if(next)next.textContent='';return}const plan=getCurrentCropPlan();const index=Number(window.currentCropPlanIndex||0)||0;const labels=plan.map(getCropPlanLabel);const activeCrop=plan[index]||'';const nextCrop=plan[index+1]||'';if(summary)summary.innerHTML=labels.length?labels.map((label,idx)=>`<span class="save-flow-chip"${idx===index?' style="background:#1f5b24;color:#fff"':''}>${label}</span>`).join(' '):'<span style="color:#6a7a6a">Choose one or more crops for this farm first.</span>';if(active)active.textContent=activeCrop?`Current crop: ${getCropPlanLabel(activeCrop)}`:'Current crop: not selected';if(next)next.textContent=nextCrop?`Next crop in queue: ${getCropPlanLabel(nextCrop)}`:'Next crop in queue: none'}
function getSelectedSurveyType(){
  const configured=window.CropCollectorApp?.services?.getSelectedSurveyConfig?.()?.survey_type||null;
  if(configured==='crop'||configured==='livestock')return configured;
  const select=document.getElementById('collector-survey-name')||document.getElementById('survey-name');
  const option=select?.selectedOptions?.[0];
  const datasetType=option?.dataset?.surveyType||option?.dataset?.type||'';
  if(datasetType==='crop'||datasetType==='livestock')return datasetType;
  const text=String(option?.textContent||select?.value||'').toLowerCase();
  if(/livestock|cattle|goat|sheep|poultry|animal|meat|dairy/.test(text))return 'livestock';
  if(/crop|agric|agriculture|winter|field|maize|tobacco|grain|sunflower/.test(text))return 'crop';
  return null;
}
function openSelectedSurveyForm({source='change'}={}){
  const selectedType=getSelectedSurveyType();
  const surveyName=String(document.getElementById('survey-name')?.value||document.getElementById('collector-survey-name')?.value||'').trim();
  if(!surveyName||!(selectedType==='crop'||selectedType==='livestock'))return false;
  setCollectorPrimaryModule(selectedType);
  const flow=getCollectorQuestionFlow(selectedType);
  const preferred=selectedType==='crop'?'crop-type':'questionnaire-id';
  const index=Math.max(1,flow.indexOf(preferred));
  setCollectorWizardStep(index);
  const active=document.querySelector('.odk-question-active')||document.getElementById('collector-odk-step-label');
  active?.scrollIntoView?.({behavior:source==='startup'?'auto':'smooth',block:'center'});
  active?.querySelector?.('input,select,textarea')?.focus?.();
  return true;
}
function refreshCollectorSurveyTypeMatch(){const cropBtn=document.getElementById('collector-open-crop');const livestockBtn=document.getElementById('collector-open-livestock');if(cropBtn){cropBtn.disabled=false;cropBtn.removeAttribute('disabled');cropBtn.title=''}if(livestockBtn){livestockBtn.disabled=false;livestockBtn.removeAttribute('disabled');livestockBtn.title=''}}
function focusCropPlanSelector(){const planner=document.getElementById('crop-plan-selector');if(!planner)return;planner.hidden=false;planner.classList.add('odk-question-active');planner.classList.add('collector-attention-pulse');planner.scrollIntoView?.({behavior:'smooth',block:'center'});const firstUnchecked=planner.querySelector('[data-crop-plan-option]:not(:checked)');const firstChecked=planner.querySelector('[data-crop-plan-option]:checked');const target=firstUnchecked||firstChecked||planner.querySelector('[data-crop-plan-option]');target?.focus?.();setTimeout(()=>planner.classList.remove('collector-attention-pulse'),1800)}
function focusCropTypeField(){const field=document.getElementById('crop-type');const group=field?.closest('.input-group');if(group){group.hidden=false;group.style.display='';group.classList.add('odk-question-active');group.classList.add('collector-attention-pulse');group.scrollIntoView?.({behavior:'smooth',block:'center'});setTimeout(()=>group.classList.remove('collector-attention-pulse'),1800)}field?.focus?.()}
function focusPhotoCaptureBlock(){const picker=document.getElementById('photo-pick-btn');const previewPanel=document.getElementById('photo-preview-panel');const clearBtn=document.getElementById('clear-photo-btn');const photoInput=document.getElementById('photo-file');window.promptPhotoEvidenceRequired?.();const target=picker||clearBtn||photoInput||previewPanel;if(target){target.classList?.add?.('collector-attention-pulse');target.scrollIntoView?.({behavior:'smooth',block:'center'});target.focus?.();setTimeout(()=>target.classList?.remove?.('collector-attention-pulse'),1800)}}
function buildDraftQuestionnaireId(module=getCurrentModule()){const now=new Date();const stamp=`${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}${String(now.getSeconds()).padStart(2,'0')}`;const prefix=module==='livestock'?'LVS':'CRP';return `${prefix}-${stamp}`}
function ensureQuestionnaireIdValue(module=getCurrentModule(),{force=false}={}){const field=document.getElementById('questionnaire-id');if(!field)return'';const currentValue=String(field.value||'').trim();if(currentValue&&!force)return currentValue;const draftId=buildDraftQuestionnaireId(module);field.value=draftId;field.dispatchEvent?.(new Event('input',{bubbles:true}));field.dispatchEvent?.(new Event('change',{bubbles:true}));collectorDebugLog(`questionnaire-id:auto-filled module=${module||'none'} value="${draftId}"`);return draftId}
function ensureAeoNameValue({force=false}={}){const field=document.getElementById('aeo-name');if(!field)return'';const currentValue=String(field.value||'').trim();if(currentValue&&!force)return currentValue;const candidate=String(window.currentUser?.displayName||window.currentUser?.username||'').trim();if(!candidate)return currentValue;field.value=candidate;field.dispatchEvent?.(new Event('input',{bubbles:true}));field.dispatchEvent?.(new Event('change',{bubbles:true}));collectorDebugLog(`aeo-name:auto-filled value="${candidate}"`);return candidate}
function focusQuestionnaireIdField(){const field=document.getElementById('questionnaire-id');const group=field?.closest('.input-group');if(group){group.classList.add('collector-attention-pulse');group.scrollIntoView?.({behavior:'smooth',block:'center'});setTimeout(()=>group.classList.remove('collector-attention-pulse'),1800)}field?.focus?.();field?.select?.()}
function syncActiveCropFromPlan(){const field=document.getElementById('crop-type');if(!field)return;const plan=getCurrentCropPlan();let index=Number(window.currentCropPlanIndex||0)||0;if(index>=plan.length)index=0;setCurrentCropPlanIndex(index);field.value=getCurrentModule()==='crop'?(plan[index]||''):'';renderCropPlanSummary()}
function setCropPlan(plan=[],{resetIndex=true}={}){setCurrentCropPlan([...new Set((plan||[]).filter(Boolean))]);if(resetIndex)setCurrentCropPlanIndex(0);syncCropPlanCheckboxes();syncActiveCropFromPlan();window.updateMobileSaveFlowState?.()}
function advanceCropPlan(){const plan=getCurrentCropPlan();const index=Number(window.currentCropPlanIndex||0)||0;if(index+1>=plan.length)return false;setCurrentCropPlanIndex(index+1);syncActiveCropFromPlan();return true}
function clearCropPlan(){setCurrentCropPlan([]);setCurrentCropPlanIndex(0);syncCropPlanCheckboxes();syncActiveCropFromPlan()}
function getSidebarSectionKey(section,index){return section?.dataset?.sectionKey||`section-${index}`}
function loadSidebarSectionState(){try{return JSON.parse(localStorage.getItem(SIDEBAR_SECTION_STATE_KEY)||'{}')}catch{return {}}}
function saveSidebarSectionState(state){localStorage.setItem(SIDEBAR_SECTION_STATE_KEY,JSON.stringify(state))}
function setSidebarSectionCollapsed(section,collapsed){if(!section)return;section.dataset.collapsed=collapsed?'true':'false';[...section.children].forEach((child,index)=>{if(index===0)return;if(collapsed){child.style.display='none'}else{if(child.id==='validate-form'){const canValidate=typeof window.hasRole==='function'&&window.hasRole('validator','admin');const activeMode=typeof window.getActiveMode==='function'?window.getActiveMode():'collect';child.style.display=(canValidate&&activeMode==='validate')?'':'none'}else if(child.id==='collect-form'){const activeMode=typeof window.getActiveMode==='function'?window.getActiveMode():'collect';child.style.display=(activeMode==='collect')?'':'none'}else if(child.classList.contains('mode-toggle')){const canValidate=typeof window.hasRole==='function'&&window.hasRole('validator','admin');child.style.display=canValidate?'':'none'}else{child.style.display=''}}});const sections=[...document.querySelectorAll('#sidebar .section')];const state=loadSidebarSectionState();state[getSidebarSectionKey(section,sections.indexOf(section))]=!collapsed;saveSidebarSectionState(state);const icon=section.querySelector('.section-toggle i');if(icon)icon.setAttribute('data-feather',collapsed?'chevron-right':'chevron-down')}
function openSidebarSection(section){if(section)setSidebarSectionCollapsed(section,false)}
function collapseSidebarSectionsExcept(...allowedSections){const allowed=new Set(allowedSections.filter(Boolean));document.querySelectorAll('#sidebar .section').forEach(section=>{if(section.id==='collector-quick-menu'||allowed.has(section))return;setSidebarSectionCollapsed(section,true)})}
function setQuickMenuActive(area){document.querySelectorAll('#collector-quick-menu button[id^="quick-menu-"]').forEach(button=>{const active=button.id===`quick-menu-${area}`;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}
function refreshCollectorQuickMenu(){const isGuest=!!(window.currentUser&&window.currentUser.isGuest);const isAdmin=!!window.hasRole?.('admin');const canValidate=!!window.hasRole?.('validator','admin');const adminLink=document.getElementById('quick-menu-admin');const logoutBtn=document.getElementById('quick-menu-logout');const validateBtn=document.getElementById('quick-menu-validate');const moreTools=document.getElementById('quick-menu-more');if(adminLink)adminLink.style.display=isAdmin?'inline-flex':'none';if(logoutBtn)logoutBtn.style.display=isGuest?'none':'flex';if(validateBtn){validateBtn.style.display=canValidate?'flex':'none';validateBtn.disabled=!canValidate}if(moreTools&&window.innerWidth>=900)moreTools.open=true}
function setCollectDetailStep(step){const basicBtn=document.getElementById('collect-step-basic');const moreBtn=document.getElementById('collect-step-more');const basicPanel=document.getElementById('collect-step-basic-panel');const morePanel=document.getElementById('collect-step-more-panel');const more=step==='more';if(basicBtn){basicBtn.classList.toggle('active',!more);basicBtn.classList.toggle('secondary',more)}if(moreBtn){moreBtn.classList.toggle('active',more);moreBtn.classList.toggle('secondary',!more)}if(basicPanel)basicPanel.hidden=more;if(morePanel)morePanel.hidden=!more;feather.replace()}
